  tools.view_image({path:"/app/runs/final_result/last/canvas_cam.jpg",detail:"original"}),
  tools.exec_command({cmd:"python -u - <<'PY'
from PIL import Image
import numpy as np
from scipy import ndimage as ndi
from scipy.signal import fftconvolve
T0=np.asarray(Image.open('/app/target.png').convert('RGB')).mean(2)<120
im=np.asarray(Image.open('/app/runs/final_result/last/canvas_cam.jpg').convert('RGB'))
s=2344.588379*.00022186/.6
Y,X=np.indices((1024,1024));xc=512+s*(X+.5-512);yc=512+s*(Y+.5-512)
labels,n=ndi.label(T0,np.ones((3,3)))
for th in [50,80,110]:
 cam=im.mean(2)<th;A=cam[np.clip(np.rint(yc).astype(int),0,1023),np.clip(np.rint(xc).astype(int),0,1023)];T=T0
 corr=fftconvolve(A.astype(np.float32),T[::-1,::-1].astype(np.float32),mode='full');h,w=T.shape;best=(-1,0,0)
 for dy in range(-20,21):
  for dx in range(-20,21):
   inter=float(corr[h-1+dy,w-1+dx]);iou=inter/(T.sum()+A.sum()-inter)
   if iou>best[0]:best=(iou,dx,dy)
 _,dx,dy=best;Ar=ndi.shift(A.astype(np.uint8),(dy,dx),order=0,mode='constant',cval=0).astype(bool)
 inter=int((Ar&T).sum());uni=int((Ar|T).sum());dT=ndi.distance_transform_edt(~T);dA=ndi.distance_transform_edt(~Ar)
 P=float(np.mean(dT[Ar]<=4.5));R=float(np.mean(dA[T]<=4.5));F=2*P*R/(P+R);stray=int((Ar&(dT>4.5)).sum())
 print('threshold',th,'IoU',round(inter/uni,3),'shift_camera_px',(dx,dy),'shift_mm',(round(dx*.6/2344.588*1000,2),round(dy*.6/2344.588*1000,2)),'boundaryF',round(F,3),'P/R',round(P,3),round(R,3),'stray_ratio',round(stray/T.sum(),3))
 print('component coverage',[round(float(((labels==i)&Ar).sum()/(labels==i).sum()),3) for i in range(1,n+1) if (labels==i).sum()>100])
PY",yield_time_ms:10000,max_output_tokens:600})
]);
if (results[0].status === "fulfilled") image(results[0].value.image_url);
